 CHECK(contacts.begin(epoch,body,world,false,error));CHECK(contacts.retire(epoch,error)&&!contacts.valid()&&!contacts.sampling()&&contacts.count()==0);CHECK(!contacts.retire(epoch,error)&&!contacts.begin(epoch,body,world,false,error));CHECK(!contacts.prepare(data,epoch,error)&&contacts.prepare(data,epoch+1,error));CHECK(!contacts.end(epoch,body,world,overlap.data(),3,error));
 // One failed receiver must not consume an enter or publish the first of a
