 DungeonKeyContacts pending;DungeonKeyClocks crowded;const uint64_t next_epoch=9000;CHECK(pending.prepare(data,next_epoch,error)&&crowded.prepare(data.clocks(),next_epoch,0,flags(data),error));uint32_t door=0;for(const auto&o:data.owners())if(data.clocks().profile(o.profile)->kind==KeyClockKind::Door)door=o.owner;CHECK(door);body={1,4353,true};overlap.fill(0);overlap[0]=overlap[1]=1;CHECK(pending.begin(next_epoch,body,crowded,false,error)&&pending.end(next_epoch,body,crowded,overlap.data(),pending.count(),error));crowded.clear_events();
 while(crowded.events().size()<4088)CHECK(crowded.interact(next_epoch,door,error));const auto before=crowded.events().size();CHECK(before==4088&&crowded.counter()==0);CHECK(!pending.begin(next_epoch,body,crowded,false,error)&&!pending.sampling()&&crowded.counter()==0&&crowded.events().size()==before);for(size_t i=0;i<2;++i){bool flag=true;CHECK(crowded.flag(next_epoch,data.shapes()[pending.shape_index(i)].owner,flag,error)&&!flag);}crowded.clear_events();CHECK(pending.begin(next_epoch,body,crowded,false,error)&&pending.sampling()&&crowded.counter()==2);CHECK(pending.end(next_epoch,body,crowded,overlap.data(),pending.count(),error)&&crowded.idle_frame(next_epoch,error));crowded.clear_events();
 const auto*stable=crowded.events().data();CHECK(pending.begin(next_epoch,body,crowded,false,error)&&crowded.events().empty()&&crowded.events().data()==stable);CHECK(pending.end(next_epoch,body,crowded,overlap.data(),pending.count(),error));CHECK(pending.retire(next_epoch,error));
 std::printf("Key contacts:%u checks;27 native settled observations/14 cases,current body/source polygon filters,paused and initial entries,other body exclusion,disabled/reentry,source audio completion and atomic capacity/epoch/resource rejection; no live map or exact-frame claim\n",checks);
